    static func withRecordBytes<Result>(
        for glyph: GlyphID,
        expectedByteCount: UInt32,
        _ body: (UnsafeRawBufferPointer) throws -> Result
    ) rethrows -> Result? {
        try withRecordBytesStorage(for: glyph, expectedByteCount: expectedByteCount, body)
    }

